/* covariance.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* Tunable blocking factor for the covariance accumulation.
 * It controls how many feature indices (i dimension) are processed together
 * for each row.  Adjust at compile time if desired, e.g.:
 *   -DCOV_BLOCK_I=64
 *
 * The current use keeps the access pattern identical in terms of which
 * elements are touched and in what numerical order each individual
 * covariance entry is accumulated; only the traversal order across
 * independent elements is changed.
 */
#ifndef COV_BLOCK_I
# define COV_BLOCK_I 32
#endif


/* Array initialization. */
static
void init_array (int m, int n,
                 DATA_TYPE *float_n,
                 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  /* Row-major traversal (i outer, j inner) already gives good locality. */
  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
                 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving numerical semantics):
   - Mean computation reordered to traverse the data matrix row-major,
     improving cache locality and enabling efficient vectorization.
     For each column j, the sequence of additions over rows i is
     unchanged (still 0..N-1), so each mean[j] is bitwise identical
     to the original implementation.
   - Covariance accumulation reorganized to iterate over rows (k) first,
     then features (i,j). This makes each row of the (already centered)
     data matrix be consumed in a single, contiguous pass, greatly
     improving spatial locality and reducing redundant loads.
     For every cov[i][j], the sequence of per-row contributions is still
     accumulated in strictly increasing k order, so each covariance entry
     is numerically identical to the original code.
   - Division by (float_n - 1) is hoisted to a separate pass after
     the accumulation, but still applied once per element exactly as
     before; the operation ordering for each cov[i][j] remains:
       sum_k(...)  followed by a single division.
*/
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
                       DATA_TYPE float_n,
                       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
                       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
                       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Create local restrict-qualified aliases to help the compiler
     with alias analysis and vectorization.  The arrays do not alias
     in this benchmark, so this is semantically valid. */
  DATA_TYPE (* __restrict data_)[M] =
    (DATA_TYPE (*)[M]) data;
  DATA_TYPE (* __restrict cov_)[M]  =
    (DATA_TYPE (*)[M]) cov;
  DATA_TYPE * __restrict mean_      =
    (DATA_TYPE *) mean;

#pragma scop

  /* --------------------------------------------------------------
   * 1. Compute column means: mean[j] = (1/n) * sum_i data[i][j]
   * --------------------------------------------------------------
   *
   * Original code:
   *   for (j)
   *     mean[j] = 0;
   *     for (i)
   *       mean[j] += data[i][j];
   *
   * New code uses a row-major traversal:
   *   - We first zero all mean[j].
   *   - Then we traverse rows i and accumulate mean[j] across columns.
   *
   * For each fixed j, the additions to mean[j] still occur in the
   * order i = 0.._PB_N-1, so floating-point results are bitwise
   * identical, but memory access is now contiguous in the inner loop.
   */

  /* Initialize means to zero. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums with row-major access to 'data_'. */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict row = data_[i];
    for (j = 0; j < _PB_M; j++)
      mean_[j] += row[j];
  }

  /* Scale by 1/n. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] /= float_n;


  /* --------------------------------------------------------------
   * 2. Subtract the mean from each column (center the data)
   * --------------------------------------------------------------
   *
   * This is already a row-major traversal, which is cache-friendly.
   * We only replace 'data'/'mean' by their restrict-qualified aliases.
   */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE * __restrict row = data_[i];
    for (j = 0; j < _PB_M; j++)
      row[j] -= mean_[j];
  }


  /* --------------------------------------------------------------
   * 3. Compute the covariance matrix
   *    cov[i][j] = sum_k data[k][i] * data[k][j] / (n - 1)
   * --------------------------------------------------------------
   *
   * Original code:
   *   for (i)
   *     for (j = i; j < M; j++) {
   *       cov[i][j] = 0;
   *       for (k)
   *         cov[i][j] += data[k][i] * data[k][j];
   *       cov[i][j] /= (float_n - 1);
   *       cov[j][i] = cov[i][j];
   *     }
   *
   * This performs strided accesses in memory (column-wise) for each
   * pair (i, j), and repeatedly walks the same columns many times.
   *
   * New structure:
   *   - First, zero the upper triangle of cov.
   *   - Then, for each row k, we traverse that row of 'data_' in a
   *     cache-friendly manner and update all relevant cov[i][j].
   *   - Finally, we divide each cov[i][j] by (float_n - 1) and
   *     symmetrize cov[j][i].
   *
   * For a fixed (i, j), the sequence of updates is still:
   *   cov[i][j] starts at 0, then receives one contribution
   *   for each k = 0.._PB_N-1 in that order, followed by
   *   one division by (float_n - 1).
   * Thus, each cov element is numerically identical to the
   * original implementation, with substantially improved
   * memory access patterns.
   */

  /* 3.a Initialize upper triangle of cov_ to zero. */
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      cov_[i][j] = SCALAR_VAL(0.0);

  /* 3.b Accumulate sums: cov_[i][j] += sum_k data_[k][i] * data_[k][j]
   *
   * We iterate over rows first (k), so each centered data row is used
   * in a single contiguous pass.  Within each row:
   *   - We (optionally) block over i using COV_BLOCK_I.
   *   - For each i, we load row[i] once (kept in xi) and then
   *     traverse j from i to M-1 contiguously.
   *
   * For every (i,j), exactly one cov_[i][j] update is performed per
   * row k, and these updates occur in the same order of k as in
   * the original triple-nested (i,j,k) loop.
   */
  for (k = 0; k < _PB_N; k++)
  {
    DATA_TYPE * __restrict row = data_[k];

    /* Block over i to allow light tuning of working-set size
       for the covariance rows. */
    int ii;
    for (ii = 0; ii < _PB_M; ii += COV_BLOCK_I)
    {
      int i_end = ii + COV_BLOCK_I;
      if (i_end > _PB_M)
        i_end = _PB_M;

      for (i = ii; i < i_end; i++)
      {
        DATA_TYPE xi = row[i];
        /* j loop remains contiguous in memory. */
        for (j = i; j < _PB_M; j++)
          cov_[i][j] += xi * row[j];
      }
    }
  }

  /* 3.c Scale by (float_n - 1) and symmetrize.
   *
   * This is separated from the accumulation phase to:
   *   - keep the inner accumulation loop purely additive/multiplicative,
   *     which tends to vectorize and pipeline better;
   *   - still preserve the original operation order: for each (i,j),
   *     all additions are completed before this single division.
   */
  {
    DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

    for (i = 0; i < _PB_M; i++)
      for (j = i; j < _PB_M; j++)
      {
        DATA_TYPE v = cov_[i][j] / denom;
        cov_[i][j] = v;
        cov_[j][i] = v;
      }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
                     POLYBENCH_ARRAY(data),
                     POLYBENCH_ARRAY(cov),
                     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
