#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stddef.h>  /* for size_t */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* Tunable blocking factor for the covariance kernel.
 * This controls how many columns (j dimension) are processed together
 * when forming the covariance matrix. It is a compile-time constant
 * that can be adjusted to match the target machine's cache hierarchy. */
#ifndef COV_BLOCK_J
# define COV_BLOCK_J 32
#endif

#if COV_BLOCK_J <= 0
# error "COV_BLOCK_J must be a positive integer"
#endif


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  /* data is stored in row-major order, so iterating i (rows) outside
   * and j (columns) inside gives contiguous accesses. */
  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Use row-major friendly traversals for computing the column means.
   - Use pointer-based linear indexing to reduce address arithmetic.
   - Block the covariance computation along the j-dimension so that,
     for a fixed column i, we accumulate multiple cov[i][j] values
     simultaneously. This allows:
       * Contiguous accesses along the inner j loop (good for cache
         and SIMD).
       * Reuse of data[k][i] across many j in the block.
   - For each covariance entry (i,j), the accumulation over k is still
     performed in strictly increasing k order, so floating-point
     round-off behavior matches the original code. */
static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Effective loop bounds (PolyBench may wrap these macros). */
  const int M_ = _PB_M;
  const int N_ = _PB_N;

  /* Flatten the 2D arrays to 1D pointers for faster address arithmetic.
   * PolyBench guarantees that these arrays are contiguous. */
  DATA_TYPE * __restrict data_lin = &data[0][0];
  DATA_TYPE * __restrict cov_lin  = &cov[0][0];
  DATA_TYPE * __restrict mean_lin = &mean[0];

  /* Row-major stride for both data and cov. */
  const int stride_data = m;
  const int stride_cov  = m;

  /* Convenience macros for indexing into the flattened arrays. */
#define DATA_ELEM(ii, jj) data_lin[(size_t)(ii) * (size_t)stride_data + (size_t)(jj)]
#define COV_ELEM(ii, jj)  cov_lin [(size_t)(ii) * (size_t)stride_cov  + (size_t)(jj)]

#pragma scop
  /* ------------------------------------------------------------------ */
  /* 1. Compute column means: mean[j] = (1/n) * sum_i data[i][j]        */
  /* ------------------------------------------------------------------ */

  /* Initialize means to zero. */
  for (j = 0; j < M_; j++)
    mean_lin[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums using row-major friendly traversal.
   *
   * For a fixed row i, data[i][0..M_-1] is contiguous in memory, which
   * leads to good spatial locality and allows vectorization in j. For
   * each column j, the sequence of additions over i is still in
   * increasing i order, identical to the original semantics. */
  for (i = 0; i < N_; i++)
  {
    const DATA_TYPE * __restrict row = data_lin + (size_t)i * (size_t)stride_data;

    /* mean[j] and row[j] do not alias; hint to the compiler that this
     * loop can be vectorized ignoring potential dependencies. */
#pragma GCC ivdep
    for (j = 0; j < M_; j++)
      mean_lin[j] += row[j];
  }

  /* Scale by 1/n. Order of operations for each mean[j] is unchanged
   * with respect to the accumulation above, so the floating-point
   * behavior matches the original code. */
  for (j = 0; j < M_; j++)
    mean_lin[j] /= float_n;


  /* ------------------------------------------------------------------ */
  /* 2. Subtract mean from data: data[i][j] -= mean[j]                  */
  /* ------------------------------------------------------------------ */

  /* This already traverses rows (i) outside and columns (j) inside,
   * which matches row-major layout and is cache friendly. We only
   * replace indexing with pointer arithmetic. */
  for (i = 0; i < N_; i++)
  {
    DATA_TYPE * __restrict row = data_lin + (size_t)i * (size_t)stride_data;

#pragma GCC ivdep
    for (j = 0; j < M_; j++)
      row[j] -= mean_lin[j];
  }


  /* ------------------------------------------------------------------ */
  /* 3. Compute covariance matrix                                       */
  /*    cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)       */
  /*    for all 0 <= i <= j < M                                         */
  /* ------------------------------------------------------------------ */

  const DATA_TYPE denom = float_n - SCALAR_VAL(1.0);

  /* Outer loop over the first column index i. */
  for (i = 0; i < M_; i++)
  {
    /* Process the second index j in blocks [jb, jb + COV_BLOCK_J). */
    for (int jb = i; jb < M_; jb += COV_BLOCK_J)
    {
      const int j_end     = jb + COV_BLOCK_J < M_ ? jb + COV_BLOCK_J : M_;
      const int block_len = j_end - jb;

      /* Local accumulators for this (i, jb..j_end-1) slice.
       * Each sum[b] accumulates cov(i, jb+b) over all k. */
      DATA_TYPE sum[COV_BLOCK_J];

      /* Initialize only the used part of the block. */
      for (j = 0; j < block_len; j++)
        sum[j] = SCALAR_VAL(0.0);

      /* Accumulate contributions from all rows.
       *
       * For each k, we:
       *   - Load data[k][i] once (scalar).
       *   - Use it to update all cov(i, j) in the current j-block,
       *     multiplying with data[k][j] for j = jb..j_end-1.
       *
       * This inner j loop accesses data[k][j] contiguously, which is
       * friendly to caches and SIMD. For each fixed pair (i, j),
       * the operations on sum[...] occur in strictly increasing k
       * order (0, 1, ..., N_-1), preserving the original numerical
       * semantics. */
      for (k = 0; k < N_; k++)
      {
        const DATA_TYPE * __restrict row =
            data_lin + (size_t)k * (size_t)stride_data;

        const DATA_TYPE x_i = row[i];

#pragma GCC ivdep
        for (j = 0; j < block_len; j++)
        {
          const DATA_TYPE x_j = row[jb + j];
          sum[j] += x_i * x_j;
        }
      }

      /* Scale by (n - 1) and write the symmetric entries in cov.
       * Each cov(i, j) is written exactly once here, and cov(j, i) is
       * set to the same value to exploit symmetry. */
      for (j = 0; j < block_len; j++)
      {
        const int jj        = jb + j;
        const DATA_TYPE val = sum[j] / denom;

        COV_ELEM(i,  jj) = val;
        COV_ELEM(jj, i ) = val;
      }
    }
  }
#pragma endscop

  /* Clean up local indexing macros to avoid leaking them outside. */
#undef DATA_ELEM
#undef COV_ELEM
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_covariance (m, n, float_n,
		     POLYBENCH_ARRAY(data),
		     POLYBENCH_ARRAY(cov),
		     POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
