static
void kernel_covariance[[gnu::flatten, gnu::noinline]](int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

  /* Create local restrict-qualified views of the input arrays.
   * This helps the compiler with alias analysis and vectorization. */
  DATA_TYPE (*restrict data_)[m] = (DATA_TYPE (*restrict)[m])data;
  DATA_TYPE (*restrict cov_)[m]  = (DATA_TYPE (*restrict)[m])cov;
  DATA_TYPE *restrict mean_      = (DATA_TYPE *restrict)mean;

  /* Precompute scalar factors used in the kernel. */
  const DATA_TYPE inv_float_n =
      SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE norm_factor =
      SCALAR_VAL(1.0) / (float_n - SCALAR_VAL(1.0));

#pragma scop
  /* -----------------------------------------------------------------------
   * 1. Compute column means.
   *
   * Original code was:
   *   for j: mean[j] = 0;
   *     for i: mean[j] += data[i][j];
   *   mean[j] /= float_n;
   *
   * We reorder loops to iterate rows first (i outer) for better data
   * locality, but for each column j the updates still occur in the same
   * i order (0..N-1), so the floating-point accumulation order per mean
   * element is preserved.
   * ----------------------------------------------------------------------- */

  /* Initialize means to zero. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums in row-major order. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict data_i = data_[i];
    for (j = 0; j < _PB_M; j++) {
      mean_[j] += data_i[j];
    }
  }

  /* Scale by 1/n. */
  for (j = 0; j < _PB_M; j++)
    mean_[j] *= inv_float_n;


  /* -----------------------------------------------------------------------
   * 2. Center the data matrix: subtract the mean from each column.
   *    (Same loop structure as original, but via restrict-qualified views.)
   * ----------------------------------------------------------------------- */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict data_i = data_[i];
    for (j = 0; j < _PB_M; j++) {
      data_i[j] -= mean_[j];
    }
  }


  /* -----------------------------------------------------------------------
   * 3. Compute the covariance matrix.
   *
   * Mathematical operation:
   *   cov = (1 / (n - 1)) * X^T * X
   * where X is the centered data matrix of size N x M.
   *
   * We perform three sub-steps:
   *   (a) Zero-initialize the upper triangular part of cov.
   *   (b) For each observation k, update cov using a blocked
   *       "k-outer" formulation that accesses data row-major:
   *
   *       for k
   *         for i
   *           for j >= i
   *             cov[i][j] += data[k][i] * data[k][j];
   *
   *       The update order over k for each (i,j) pair matches the
   *       original code (k = 0..N-1), so the accumulation order per
   *       covariance element is preserved.
   *
   *   (c) Normalize all entries by (n - 1) and symmetrize the matrix.
   * ----------------------------------------------------------------------- */

  /* (a) Initialize the upper triangle. */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *restrict cov_i = cov_[i];
    for (j = i; j < _PB_M; j++) {
      cov_i[j] = SCALAR_VAL(0.0);
    }
  }

  /* (b) Accumulate X^T X using blocking over feature indices (i, j).
   *     Blocking improves cache reuse for the cov_ matrix when M is large.
   */
  for (k = 0; k < _PB_N; k++) {
    DATA_TYPE *restrict data_k = data_[k];

    for (int i0 = 0; i0 < _PB_M; i0 += COV_BLOCK_I) {
      int i_max = i0 + COV_BLOCK_I;
      if (i_max > _PB_M)
        i_max = _PB_M;

      /* Start j-blocks at i0 to skip blocks entirely below the diagonal.
       * Inside each block we still enforce j >= i to stay in the upper
       * triangle and avoid redundant work.
       */
      for (int j0 = i0; j0 < _PB_M; j0 += COV_BLOCK_J) {
        int j_max = j0 + COV_BLOCK_J;
        if (j_max > _PB_M)
          j_max = _PB_M;

        for (i = i0; i < i_max; i++) {
          DATA_TYPE xki = data_k[i];
          DATA_TYPE *restrict cov_i = cov_[i];

          /* Ensure we remain in the upper triangle: j >= i. */
          int j_start = (j0 < i) ? i : j0;

#pragma GCC ivdep
          for (j = j_start; j < j_max; j++) {
            cov_i[j] += xki * data_k[j];
          }
        }
      }
    }
  }

  /* (c) Normalize and symmetrize.
   *     After this, cov[j][i] == cov[i][j] for all i, j.
   */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *restrict cov_i = cov_[i];

    /* Diagonal element. */
    cov_i[i] *= norm_factor;

    /* Off-diagonal elements: scale and mirror to the lower triangle. */
    for (j = i + 1; j < _PB_M; j++) {
      DATA_TYPE v = cov_i[j] * norm_factor;
      cov_i[j] = v;
      cov_[j][i] = v;
    }
  }
#pragma endscop

}


